    public void load(ResultSet rs, int id) throws SQLException {
        this.id = id;
        java.sql.Date date;
        date = rs.getDate(2);
        if (date != null) this.dateCreated = new OADate(date);
        this.firstName = rs.getString(3);
        this.lastName = rs.getString(4);
        this.code = rs.getString(5);
        this.loginId = rs.getString(6);
        this.password = rs.getString(7);
        date = rs.getDate(8);
        if (date != null) this.inactiveDate = new OADate(date);
        this.newOrderAccess = (rs.getShort(9) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_NewOrderAccess, rs.wasNull());
        this.initials = rs.getString(10);
        this.adminAccess = (rs.getShort(11) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_AdminAccess, rs.wasNull());
        this.prodViewAccess = (rs.getShort(12) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_ProdViewAccess, rs.wasNull());
        this.prodShippingAccess = (rs.getShort(13) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_ProdShippingAccess, rs.wasNull());
        this.prodManagerAccess = (rs.getShort(14) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_ProdManagerAccess, rs.wasNull());
        this.salesViewAccess = (rs.getShort(15) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_SalesViewAccess, rs.wasNull());
        this.salesUserAccess = (rs.getShort(16) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_SalesUserAccess, rs.wasNull());
        this.phoneWork = rs.getString(17);
        this.phoneHome = rs.getString(18);
        this.phoneCell = rs.getString(19);
        this.email = rs.getString(20);
        this.prodAssignedToList = (rs.getShort(21) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_ProdAssignedToList, rs.wasNull());
        this.salesAssignedToList = (rs.getShort(22) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_SalesAssignedToList, rs.wasNull());
        this.salesPersonList = (rs.getShort(23) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_SalesPersonList, rs.wasNull());
        this.prodInspectorList = (rs.getShort(24) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_ProdInspectorList, rs.wasNull());
        this.salesAccess = rs.getInt(25);
        this.productionAccess = rs.getInt(26);
        this.customerAccess = rs.getInt(27);
        this.itemAccess = rs.getInt(28);
        this.pricingAccess = rs.getInt(29);
        this.searchAccess = rs.getInt(30);
        int appUserFkey = rs.getInt(31);
        setFkeyProperty(P_AppUser, rs.wasNull() ? null : appUserFkey);

        this.changedFlag = false;
        this.newFlag = false;
    }
